def build(a):
    n = a["cols"] * a["rows"]
    rigid = RIGID.format(extra=a["extra"])
    body = a["body"].replace("{soft}", SOFT).replace("{rigid}", rigid)
    head = "SLIME KING: %s. Written 2026-11-11. %s\n\n%s\n\n%s\n\n" % (a["title"], a["intro"], a["what"], LESSONS)
    how = """HOW TO USE
- ChatGPT first (the King's idle came out excellent from it: it keeps the size, the floor and the spacing); Gemini is the second try. Attach ONE image: Animations/SlimeKing/reference_image.png (the accepted King look: ivory slime, golden crown with a ruby and sapphires, golden jewelled staff held by a floating white glove, calm smug face, on magenta). Ask for a %s image, as large as it will give you. Paste everything between the two lines of equals signs.
- Generate several and keep the best. Save it in inbox/ (for example inbox/slime_king_%s_sheet.png) and tell me. I cut it, check it and put it in the page.
- OPTIONAL second try if the creature drifts (a different King, a changed crown or staff, the wrong size): also attach the idle sheet (Animations/SlimeKing/idle/source/idle_sheet.png) and put this sentence first: 'The second image is only the SAME CREATURE at the same size on the same floor, to copy exactly. Draw the poses described below in a new sheet, not the idle breath, and make the creature SMALLER in its panels than in the second image.'
- What I check: %s
- Planned cut: %s
""" % (a["ratio"], a["tag"], a["check"], a["cut"])
    rep = REPLIES.format(specific=a["specific"]) + "\n\n"
    grid = "%d columns x %d rows, %s equal panels" % (a["cols"], a["rows"], {6: "six", 8: "eight"}[n])
    first = a["what"].split("WHAT IT IS. ", 1)[1].split(". ")[0] + "."
    prompt = """==============================================================================
OUTPUT: exactly ONE static image, a sprite sheet, and nothing else. Do NOT create a GIF, an animation, a video, a preview, extra images, alternate versions or a second attempt. No other files.

Create the sprite sheet: a grid of %s, read left to right, top row first, then the bottom row. %s Every panel is one still pose, drawn crisp and clean; the motion is in the DIFFERENCE between the panels, never drawn inside one.

%s

%s

%s

""" % (grid, first, CHARACTER, (VIEW + " " + a.get("view_extra", "")).strip(), body)
    prompt += BACKGROUND + "\n\nFINAL REMINDER: output ONE single static image only. No GIF, no extra images. " + a["final"] + "\n==============================================================================\n"
    return head + how + rep + prompt


if __name__ == "__main__":
    for a in ANIMS:
        d = os.path.join(ROOT, "Animations", "SlimeKing", a["folder"], "source")
        os.makedirs(d, exist_ok=True)
        path = os.path.join(d, a["folder"] + "_prompt.txt")
        open(path, "w", encoding="utf-8").write(build(a))
        print("wrote", os.path.relpath(path, ROOT), os.path.getsize(path), "bytes")
